<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {request} from './service';import GitCalendar from './GitCalendar.vue';
const state=ref(null),posts=ref([]),pick=ref(null),busy=ref(false),error=ref('');const playing=computed(()=>state.value?.records.library.filter(r=>r.status==='playing')||[]),shelf=computed(()=>state.value?.records.library.slice(0,6)||[]),drafts=computed(()=>posts.value.filter(p=>p.status==='draft'));
const characters={atri:['atri-02','atri-18','atri-24'],charlotte:['charlotte-00','charlotte-07','charlotte-25'],wada:['wada-00','wada-01','wada-09'],cafe:['cafe-00','cafe-13','cafe-28'],flower:['flower-03','flower-19','flower-34'],may:['may-15','may-16','may-35']};const character=computed(()=>{const s=state.value;return characters[s?.profile.scene||'atri'][s?.story.scene%3||0];});
async function load(){try{[state.value,posts.value]=await Promise.all([request('/api/private/state'),request('/api/studio/posts')]);}catch(e){error.value=e.message;}}onMounted(load);
async function interact(){busy.value=true;try{state.value.story=await request('/api/private/story/click','POST',{});}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function finish(){await request('/api/private/story/finish','POST',{});await load();}function draw(){const list=state.value.records.library.filter(r=>r.status!=='done');pick.value=list.length?list[Math.floor(Math.random()*list.length)]:null;}
async function advance(item){busy.value=true;try{await request('/api/private/records/library/'+item.id,'PUT',{...item,progress:Math.min(item.total,item.progress+1)});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function seed(item){return '/moments?thought='+encodeURIComponent('关于《'+item.title+'》：');}let audio;onBeforeUnmount(()=>audio?.pause());function greet(){audio?.pause();audio=new Audio('/assets/'+(state.value.profile.voice||'greeting-00')+'.wav');audio.volume=.45;audio.play().catch(()=>{error.value='暂时无法播放语音';});}
</script>
<template><section class="room-suite"><p v-if="error" role="alert">{{error}}</p><template v-if="state"><div class="room-welcome-line"><span class="space-eyebrow">PLAYER {{state.profile.name}} · SAVE SLOT 01</span><span>今日主线：把喜欢的日子继续下去。</span></div><div class="room-stage"><div class="room-stage-copy"><span class="room-chapter">{{state.profile.season}} / 第 {{state.story.round}} 周目</span><h1>欢迎回到<br/><em>你的私人据点。</em></h1><p>{{state.profile.tagline}}</p><div><RouterLink class="room-write" to="/article/addArticle">✎ 写下新的篇章</RouterLink><RouterLink to="/moments">发一条此刻的心情 →</RouterLink></div><span class="room-stage-tags">{{state.profile.interests||'这里的喜好，由你亲手填满。'}}</span></div><div class="room-companion"><span class="companion-pin">FAVORITE CHARACTER / 每日相遇</span><button @click="interact" :disabled="busy" aria-label="与角色互动"><img :src="'/assets/'+character+'.webp'" alt="房间里的角色"/></button><p aria-live="polite">{{state.story.lastLine||'存档点已亮起。今天想继续哪一段故事？'}}</p><div><span>好感 {{state.story.points}}</span><button @click="greet">♫ 听一句问候</button></div><button v-if="state.story.phase!=='normal'" class="chapter-finish" @click="finish">{{state.story.phase==='transition'?'一周目已存档，开启二周目':'收下后日谈，继续日常'}} →</button></div></div><div class="room-ribbon"><RouterLink to="/article/articleList"><b>{{drafts.length}}</b> 篇未完待续的草稿</RouterLink><RouterLink to="/life/library"><b>{{playing.length}}</b> 个正在进行的故事</RouterLink><RouterLink to="/life/tasks"><b>{{state.records.tasks.filter(t=>t.status!=='done').length}}</b> 件生活支线</RouterLink><RouterLink to="/life/review">翻开这周的后日谈 ↗</RouterLink></div><div class="room-main-grid"><section class="room-panel playing-panel"><header><div><span class="space-eyebrow">CONTINUE PLAYING</span><h2>今晚，续上哪一段？</h2></div><RouterLink to="/life/library">收藏库 ↗</RouterLink></header><p v-if="!playing.length" class="room-empty">把正在玩的游戏、追的番放进收藏库，这里就会留下你的进度。</p><article v-for="item in playing.slice(0,3)" :key="item.id" class="playing-item"><img :src="item.cover" :alt="item.title"/><div><small>{{item.kind}} · {{item.route||item.creator}}</small><h3>{{item.title}}</h3><p>{{item.note||'还没结束的故事，继续存档。'}}</p><div class="playing-meter"><i :style="{width:Math.min(100,item.progress/item.total*100)+'%'}"/></div><div class="playing-actions"><span>{{item.progress}} / {{item.total}}</span><button @click="advance(item)" :disabled="busy||item.progress>=item.total">进度 +1</button><RouterLink :to="seed(item)">写点感想 ↗</RouterLink></div></div></article></section><aside class="room-side-stack"><section class="room-panel next-chapter"><span class="space-eyebrow">NEXT CHAPTER</span><h2>留给下一次灵感。</h2><RouterLink v-for="p in drafts.slice(0,3)" :key="p.id" :to="'/article/editArticle?articleId='+p.id"><span>草稿 / {{p.updated.slice(0,10)}}</span><strong>{{p.title}} ↗</strong></RouterLink><p v-if="!drafts.length">此刻没有待续的草稿。写篇长文，或只说一句喜欢。</p><div class="room-mini-actions"><RouterLink to="/moments">发说说</RouterLink><RouterLink to="/albums">整理相册</RouterLink></div></section><section class="room-panel tonight-draw"><span class="space-eyebrow">THE BACKLOG LOTTERY</span><h2>今晚开哪个坑？</h2><p>{{pick?pick.title:'选择困难的时候，让收藏库替你做一次决定。'}}</p><button @click="draw" :disabled="!state.records.library.some(r=>r.status!=='done')">↻ 抽一个未完的故事</button><RouterLink v-if="pick" :to="seed(pick)">记录这次相遇 →</RouterLink></section></aside></div><section class="room-panel room-shelf"><header><div><span class="space-eyebrow">MY LITTLE OBSESSIONS</span><h2>认真喜欢的东西，值得占据一个位置。</h2></div><RouterLink to="/life/library">布置收藏架 ↗</RouterLink></header><div class="shelf-items"><RouterLink v-for="item in shelf" :key="item.id" to="/life/library"><img :src="item.cover" :alt="item.title"/><span>{{item.kind}} / {{item.status==='done'?'已通关':item.status==='wish'?'想玩想看':'进行中'}}</span><h3>{{item.title}}</h3><p>{{item.quote||item.character||item.tags}}</p></RouterLink><RouterLink class="empty-shelf" to="/life/library"><b>＋</b><span>给下一个本命留位置</span></RouterLink></div></section><GitCalendar/></template></section></template>
